#!/usr/bin/env node
import { appendFile, readFile } from "node:fs/promises";
import process from "node:process";
import { z } from "zod";
import { supermemo } from "supermemo";
import dayjs from "dayjs";

//#region src/core.ts
const logRecordSchema = z.object({
  date: z.preprocess((val) => new Date(String(val)), z.date()),
  problem: z.preprocess((val) => Number(String(val)), z.number().int()),
  confidence: z.preprocess((val) => Number(String(val)), z.number()),
  skip: z
    .preprocess(
      (val) => (val ? String(val).toLowerCase() === "true" : false),
      z.boolean(),
    )
    .default(false),
});
async function readLogFromFile(filepath) {
  return readLog(await readFile(filepath, "utf8"));
}
function readLog(fileContent) {
  const lines = fileContent.split("\n");
  const records = [];
  for (const line of lines) if (line.trim()) records.push(parseLine(line));
  return records;
}
function parseLine(line) {
  const parts = line.split(" ");
  const recordDict = {};
  for (const part of parts) {
    const [key, value] = part.split("=");
    if (!key || !value) throw new Error(`invalid log record: ${line}`);
    recordDict[key] = value;
  }
  const result = logRecordSchema.safeParse(recordDict);
  if (!result.success) throw new Error(`invalid log record: ${line}`);
  return result.data;
}

