//#region src/problemset-parser.ts
const TopicTag = z.object({
  name: z.string(),
  slug: z.string(),
  __typename: z.literal("CommonTagNode"),
});
const ProblemSetQuestionNodeSchema = z.object({
  difficulty: z.enum(["EASY", "MEDIUM", "HARD"]),
  id: z.number(),
  paidOnly: z.boolean(),
  questionFrontendId: z.string(),
  status: z.string(),
  title: z.string(),
  titleSlug: z.string(),
  topicTags: z.array(TopicTag),
  frequency: z.null(),
  isInMyFavorites: z.boolean(),
  acRate: z.number(),
  contestPoint: z.null(),
  __typename: z.literal("ProblemSetQuestionNode"),
});
const ProblemSetSchema = z.object({
  data: z.object({
    problemsetQuestionListV2: z.object({
      questions: z.array(ProblemSetQuestionNodeSchema),
    }),
  }),
});

//#endregion
//#region src/data.ts
const parsedProblemSet = ProblemSetSchema.parse(problems_default);
const PREMIUM_PROBLEMS = new Set(
  parsedProblemSet.data.problemsetQuestionListV2.questions
    .filter((q) => q.paidOnly)
    .map((q) => q.id),
);

//#endregion
//#region src/review.ts
const INTERVAL_FACTOR = 7;
/**
 * Creates a new review item with default values
 */
const createReviewItem = (problemNumber, initialDate) => ({
  problemNumber,
  sm2Item: {
    interval: 0,
    repetition: 0,
    efactor: 2.5,
  },
  attemptDate: initialDate,
  dueDate: initialDate,
  numAttempts: 0,
  frustrationScore: 0,
});
/**
 * Updates a review item based on practice results
 */
const practiceReviewItem = (reviewItem, grade, attemptDate) => {
  const newSm2Item = supermemo(reviewItem.sm2Item, grade);
  const nDays = newSm2Item.interval * INTERVAL_FACTOR;
  const newDueDate = dayjs(attemptDate).add(nDays, "day").format("YYYY-MM-DD");
  const newNumAttempts = reviewItem.numAttempts + 1;
  return {
    problemNumber: reviewItem.problemNumber,
    sm2Item: newSm2Item,
    attemptDate,
    dueDate: newDueDate,
    numAttempts: newNumAttempts,
    frustrationScore: newNumAttempts / newSm2Item.efactor,
  };
};
/**
 * Converts confidence score to SuperMemo grade
 */
const mapConfidenceToGrade = (confidence) => {
  if (confidence < 0.5) return 1;
  if (confidence < 0.7) return 2;
  if (confidence < 0.9) return 3;
  if (confidence < 1) return 4;
  return 5;
};
/**
 * Processes log records and returns sorted review items
 */
const processLogRecords = (logRecords) => {
  const problemsToSkip = new Set(
    logRecords.filter((record) => record.skip).map((record) => record.problem),
  );
  const sortedRecords = [
    ...logRecords.filter((record) => !problemsToSkip.has(record.problem)),
  ].sort((a, b) => a.date.getTime() - b.date.getTime());
  const reviewMap = /* @__PURE__ */ new Map();
  for (const record of sortedRecords) {
    const { problem: problemNumber, date } = record;
    const dateStr = date.toISOString();
    if (!reviewMap.has(problemNumber)) {
      reviewMap.set(problemNumber, createReviewItem(problemNumber, dateStr));
    }
    const updatedItem = practiceReviewItem(
      reviewMap.get(problemNumber),
      mapConfidenceToGrade(record.confidence),
      dateStr,
    );
    reviewMap.set(problemNumber, updatedItem);
  }
  return [...reviewMap.values()].sort((a, b) => {
    const dateA = dayjs(a.dueDate).valueOf();
    const dateB = dayjs(b.dueDate).valueOf();
    if (dateA !== dateB) return dateA - dateB;
    return b.frustrationScore - a.frustrationScore;
  });
};
/**
 * Main review function
 */
const review = async (logFile, n, premium = false) => {
  const sortedReviewItems = processLogRecords(
    (await readLogFromFile(logFile)).filter(
      (record) => PREMIUM_PROBLEMS.has(record.problem) === premium,
    ),
  );
  for (const item of sortedReviewItems.slice(0, n)) {
    const lcidccUrl = `https://lcid.cc/${item.problemNumber}`;
    console.log(`${item.dueDate} -- ${lcidccUrl}`);
  }
};

//#endregion
//#region src/index.ts
const INCLUDE_PREMIUM = false;
const SOLUTIONS_FILE = "./solutions.log";
await main();
async function main() {
  const args = process.argv.slice(2);
  const command = args.shift();
  switch (command) {
    case "help":
      printHelp();
      break;
    case "next": {
      const n = args.shift();
      await review(SOLUTIONS_FILE, n ? parseInt(n) : 1, INCLUDE_PREMIUM);
      break;
    }
    case "add": {
      const problemNumber = args.shift();
      const confidence = args.shift();
      const skip = args.shift() === "skip";
      if (!problemNumber || !confidence) {
        console.error("problem number and confidence are required");
        process.exit(1);
      }
      const problemNumberInt = parseInt(problemNumber);
      if (isNaN(problemNumberInt)) {
        console.error(
          `problem number must be an integer; got: ${problemNumber}`,
        );
        process.exit(1);
      }
      const confidenceFloat = parseFloat(confidence);
      if (isNaN(confidenceFloat)) {
        console.error(`confidence must be a number; got: ${confidence}`);
        process.exit(1);
      }
      if (confidenceFloat < 0 || confidenceFloat > 1) {
        console.error(
          `confidence must be between 0 and 1; got: ${confidenceFloat}`,
        );
        process.exit(1);
      }
      let logEntry = `date=${
        /* @__PURE__ */ new Date().toISOString().split("T")[0]
      } problem=${problemNumberInt.toString().padStart(4, "0")} confidence=${confidenceFloat.toFixed(
        1,
      )}`;
      if (skip) logEntry += " skip=true";
      await appendFile(SOLUTIONS_FILE, logEntry + "\n");
      break;
    }
    case "debug:show-json-log": {
      const logFile = args.shift();
      if (!logFile) throw new Error("no log file provided");
      const records = await readLogFromFile(logFile);
      console.log(JSON.stringify(records, null, 2));
      break;
    }
    default:
      console.log(`Error: invalid command: ${command}`);
      console.log();
      printHelp();
      process.exit(1);
  }
}
function printHelp() {
  console.log(`Usage: lc-review <command> [options]

Commands:

    lc-review help

        Prints this help message.

    lc-review next [n_items]

        Gets the next N items for review.
        - n_items: (optional) The number of items to review (default: 1)

    lc-review add <problem_number> <grade> [skip]

        Adds a problem with a grade to the log.
        - problem_number: The problem number (integer)
        - grade: The grade for the problem (integer)

Debug commands:

    debug:show-json-log <log_file>
`);
}

//#endregion
export {};
